-- Class notes synopsis batch 11: Devil's Claw through Garlic
-- Devil's Claw: migration 442 used a straight apostrophe but common_name has a curly apostrophe (U+2019) -- use id instead

-- Devil's Claw id=80
UPDATE herbal.herbs
SET class_notes_synopsis = $$<strong>Devil's Claw</strong> is an <strong>anti-inflammatory</strong> for <strong>endometriosis</strong> pain. For animals (especially cats): a gentler alternative to <a href="?herb=87"><strong>Willow</strong></a> bark - alongside <a href="?herb=1597"><strong>Frankincense</strong></a> (Boswellia) or MSM - as recommended by David Winston.$$
WHERE id = 80;

UPDATE herbal.herbs
SET class_notes_synopsis = $$<strong>Fennel</strong> is a <strong>warming</strong>, <strong>drying</strong>, <strong>relaxing</strong>, <strong>carminative</strong>, <strong>antispasmodic</strong>, and <strong>bitter</strong> herb - GI carminative rich in <strong>volatile oils</strong>; use the seeds, which smell like licorice/anise (found everywhere). Primary use is for <strong>bloating</strong> and <strong>gas</strong> - "bowl on the table"; clears wind/gas/bloating and moves energy downward in the body - useful for <strong>scattered thoughts</strong>. As <strong>antispasmodic</strong> for <strong>spasmodic diarrhea</strong> alongside <a href="?herb=136"><strong>Catnip</strong></a>, <a href="?herb=84"><strong>Chamomile</strong></a>, <a href="?herb=167"><strong>Cinnamon</strong></a>, <a href="?herb=55"><strong>Peppermint</strong></a>, and <a href="?herb=124"><strong>Ginger</strong></a>; for <strong>upper GI excess with pain</strong>. Supports secretions in upper GI and aids digestive function. As <strong>galactagogue</strong>: carminative action gets into breast milk and helps gassy babies. Also a <strong>warming bitter for rekindling digestive fire</strong> alongside <a href="?herb=124"><strong>Ginger</strong></a>, <a href="?herb=203"><strong>Turmeric</strong></a>, <a href="?herb=167"><strong>Cinnamon</strong></a>, <a href="?herb=172"><strong>Artichoke</strong></a> leaf, and <a href="?herb=748"><strong>Sweet Orange</strong></a> peel. For <strong>poor circulation and digestive stagnation</strong>. Listed as a spice for <strong>Hot constitution</strong> - cooling; part of the classic "Cumin, Coriander, Fennel" combo for inflamed conditions ("gives good tools to the gut"). As a bitter and carminative for <strong>rheumatoid arthritis</strong>. Essential oil applied topically directly on the <strong>liver</strong> for <strong>metabolic-associated fatty liver disease</strong>. For pets: warming carminative - can mix with <a href="?herb=84"><strong>Chamomile</strong></a>; for digestive use if pet vomits food several hours later with mucus. Part of fall self-care morning juicing blend with <a href="?herb=134"><strong>Lemon Balm</strong></a> and <a href="?herb=43"><strong>Nettle</strong></a>. In <a href="?herb=16"><strong>Rhodiola</strong></a>, <a href="?herb=127"><strong>Cardamom</strong></a>, Fennel tincture at five drops three times a day. In colic tincture formula (1 part) with <a href="?herb=122"><strong>Dandelion</strong></a> root, <a href="?herb=78"><strong>Licorice</strong></a>, and <a href="?herb=55"><strong>Peppermint</strong></a>; in gut healing tea (with <a href="?herb=136"><strong>Catnip</strong></a>, <a href="?herb=84"><strong>Chamomile</strong></a>, <a href="?herb=124"><strong>Ginger</strong></a>) for <strong>childhood diarrhea</strong>; in bulk-building candy for <strong>childhood constipation</strong> (with <a href="?herb=78"><strong>Licorice</strong></a>, <a href="?herb=45"><strong>Marshmallow</strong></a> root, <a href="?herb=2240"><strong>Psyllium</strong></a> seed, and dried fruit); in glycerite with <a href="?herb=84"><strong>Chamomile</strong></a> and <a href="?herb=90"><strong>Linden</strong></a> for post-menopausal <strong>gas and bloating after meals</strong>. Digestion decoction recipe (to 32 oz water): 14g Fennel, 28g <a href="?herb=37"><strong>Yellow Dock</strong></a>, 28g <a href="?herb=54"><strong>Elecampane</strong></a>; add 10-15% tincture. Note: volatile oils not ideal for standard decoction - cover the pot to retain volatile oils. <strong>Avoid if pregnant - Fennel EO/hydrosol can cause seizures.</strong>$$
WHERE common_name = 'Fennel';

UPDATE herbal.herbs
SET class_notes_synopsis = $$<strong>Fenugreek</strong> (Trigonella foenum-graecum) is a <strong>warming</strong>, <strong>bitter</strong>, <strong>carminative</strong>, and <strong>galactagogue</strong> herb. Actions include <strong>blood sugar regulation</strong>: increases <strong>insulin sensitivity</strong>, decreases <strong>LDL</strong> and <strong>VLDL</strong> cholesterol, and lowers fasting glucose and Hemoglobin A1C. Must be used in high doses for efficacy: 5-30g/day; tincture 3-4ml QID, powder 3-7g TID. Can be used in food (curries, stews, tea) - seeds and Methi leaf (the backbone of curry blends) both useful; tastes good, high compliance. Source of <strong>Vitamin A</strong> / Beta carotene. As <strong>galactagogue</strong>: encourages breast milk production especially in the first few days after birth. <strong>Warming bitter for hypochlorhydria</strong>. GI carminative rich in <strong>volatile oils</strong>; good after meals for <strong>gas and digestive discomfort</strong>. For <strong>Cold Dry Constipation</strong>: use as decoction. Recommended for both <strong>Wet and Dry constitutions</strong>. In "Temple of Devotion" <strong>PCOS</strong> formula for blood sugar regulation. <strong>Contraindicated with Pioglitazone (Actos) - synergistic interaction; avoid combination.</strong>$$
WHERE common_name = 'Fenugreek';

UPDATE herbal.herbs
SET class_notes_synopsis = $$<strong>Feverfew</strong> is indicated for <strong>heat excess headaches</strong>. In <strong>eczema</strong> materia medica. In anti-cancer formula 2 - the more intense formula used in stages after formula 1.$$
WHERE common_name = 'Feverfew';

UPDATE herbal.herbs
SET class_notes_synopsis = $$<strong>Figwort</strong> (Scrophularia nodosa - species name "nodosa" refers to lymph nodes) is a strong <strong>lymphatic</strong>, <strong>lymphagogue</strong>, and <strong>alterative</strong> - "King's fever" herb. Indicated for <strong>immune system stagnation</strong>, <strong>edema</strong>, sluggish cleansing pathways, <strong>skin conditions</strong>, dehydration, and sedentary lifestyle. As <strong>lymphagogue</strong> for <strong>dissolving hardened lymph nodes</strong> and for <strong>accumulation with aging</strong>. Compare regional affinity: <a href="?herb=28"><strong>Cleavers</strong></a> for neck/throat, <a href="?herb=981"><strong>Red Root</strong></a> for midsection, Figwort overall. As <strong>alterative</strong> for clearing excess androgens circulating in the blood alongside <a href="?herb=22"><strong>Burdock</strong></a>, <a href="?herb=40"><strong>Sarsaparilla</strong></a>, and <a href="?herb=37"><strong>Yellow Dock</strong></a>.$$
WHERE common_name = 'Figwort';

UPDATE herbal.herbs
SET class_notes_synopsis = $$<strong>Flax</strong> seed is a <strong>demulcent</strong>, <strong>cooling</strong>, and <strong>bulk-building</strong> herb for <strong>digestive</strong> and <strong>hormonal</strong> support. As <strong>demulcent</strong> for <strong>leaky gut</strong> alongside <a href="?herb=45"><strong>Marshmallow</strong></a> - soothes and protects the gut mucosal lining; full reset and healing may take ~6 months. Also demulcent for <strong>sore throat</strong> (flax seed tea specifically good for sore throat). For <strong>Hot Dry Constipation</strong>: demulcent cooling herb. For <strong>childhood constipation</strong>: bulk-building herb. Paired with <a href="?herb=167"><strong>Cinnamon</strong></a> for its moistening properties to counteract Cinnamon's drying effect (caution in severe constipation). GI demulcent - prefer glycerites, honeys, or vinegars over alcohol for digestive use. Flax seed 1-2 tablespoons daily on food, cooked in, or in a smoothie - good source of <strong>short-chain fatty acids</strong> and fiber for <strong>PMOS</strong>; also used in patient protocols for <strong>hormonal support</strong>.$$
WHERE common_name = 'Flax';

UPDATE herbal.herbs
SET class_notes_synopsis = $$<strong>Fo Ti</strong> is an <strong>adaptogen</strong> and <strong>reproductive tonic</strong> - adaptogens "help rewrite the story"; many adaptogens are also repro tonics.$$
WHERE common_name = 'Fo Ti';

UPDATE herbal.herbs
SET class_notes_synopsis = $$<strong>Frankincense</strong> (Boswellia resin) is an <strong>anti-inflammatory</strong> - a prized resin used historically alongside <a href="?herb=99"><strong>Myrrh</strong></a> for anointing tabernacle, temple, body, and burial. Anti-inflammatories promote <strong>healthy inflammation</strong> by regulating it to turn on and off rather than simply suppressing it; indicated for <strong>musculoskeletal discomfort</strong>, <strong>sprains</strong>, <strong>strains</strong>, <strong>headaches</strong>, wounds, and <strong>chronic internal conditions</strong>. Boswellic acid reduces volatile acids and combats <strong>chronic joint inflammation</strong>; used in salve with <a href="?herb=114"><strong>Arnica</strong></a> for topical anti-inflammatory application. Combined with <a href="?herb=203"><strong>Turmeric</strong></a> in "Curamed" for anti-inflammatory support in <strong>pancreatitis</strong>. For <strong>depression</strong> with other signs of <strong>systemic inflammation</strong>, especially with <strong>GI inflammation</strong>. For animals: good for <strong>mobility</strong> and pain relief in older animals; given in capsules as powder. Also a gentler alternative to <a href="?herb=87"><strong>Willow</strong></a> bark for cats (alongside Devil's Claw or MSM). <strong>Frankincense resin does not extract in water - decoction is not appropriate; use alcohol-based menstruum or infused oil to extract the anti-inflammatory resins.</strong>$$
WHERE id = 1597;

UPDATE herbal.herbs
SET class_notes_synopsis = $$<strong>Fringetree</strong> is indicated for <strong>lower GI deficiency</strong> (congestive type) - used to stimulate.$$
WHERE common_name = 'Fringetree';

UPDATE herbal.herbs
SET class_notes_synopsis = $$<strong>Garlic</strong> is a <strong>pungent</strong>, <strong>warming</strong>, <strong>antimicrobial</strong>, <strong>antiviral</strong>, <strong>antifungal</strong>, <strong>expectorant</strong>, <strong>anticatarrhal</strong>, <strong>anticarcinogenic</strong>, and <strong>cardiovascular</strong> herb - the #1 heart medicine; lowers <strong>LDL</strong> and increases <strong>HDL</strong> to reduce inflammation. Listed in the African American Materia Medica (108 documented species) and in Black Herbal cardiovascular materia medica. As <strong>antiviral</strong>: at first sign of virus, chop 1/2 clove, let oxidize a minute, then take like a pill every 2-4 hours; also antifungal and expectorant. As <strong>antimicrobial</strong>: for <strong>sore throat</strong> (raw), <strong>infected wounds and animal bites</strong> (applied as tincture or liniment externally), <strong>common cold</strong>, and <strong>bacterial infections</strong>. For <strong>pneumonia</strong> when Western Medicine unavailable: 5-7 cloves raw per day, swallowed in honey as small pill-sized pieces without chewing. As <strong>anticatarrhal</strong> alongside <a href="?herb=309"><strong>Yerba Mansa</strong></a>, <a href="?herb=30"><strong>Goldenseal</strong></a>, and <a href="?herb=50"><strong>Boneset</strong></a>. As <strong>antimicrobial</strong> alongside <a href="?herb=59"><strong>Thyme</strong></a>, <a href="?herb=54"><strong>Elecampane</strong></a>, and <a href="?herb=112"><strong>Usnea</strong></a>. As <strong>anticarcinogenic</strong>: inhibits, mitigates, prevents, and can help cure cancer; in anti-cancer formula 1 to quickly change the environment in early-stage cancer; in anti-cancer formula 2 (more intense formula used in stages after formula 1); in soups for immunity. For <strong>cardiovascular</strong> support: in Black Herbal materia medica, listed as anti-bacterial alongside red onion in traditional Black American herbalism. For <strong>blood pressure reduction in pregnancy</strong> - lean into pestos as food-medicine approach. For <strong>earaches</strong>: Garlic mullein flower oil infusion for ear infections and congestion-type <strong>earaches in children</strong> (along with warm packs on lower back and decongestant tea). In the <strong>Deep Lung Formula</strong> for <strong>bronchitis</strong> with <a href="?herb=54"><strong>Elecampane</strong></a>, <a href="?herb=65"><strong>Angelica</strong></a>, <a href="?herb=590"><strong>Yerba Santa</strong></a>, <a href="?herb=44"><strong>Yarrow</strong></a>, <a href="?herb=73"><strong>Hawthorn</strong></a>, <a href="?herb=61"><strong>Mullein</strong></a>, <a href="?herb=309"><strong>Yerba Mansa</strong></a>, and <a href="?herb=104"><strong>Osha</strong></a>. In <strong>Four Thieves Vinegar</strong> and <strong>Fire Cider</strong> (antimicrobial; Fire Cider is a famous cold and flu remedy). Garlic skins as decoction to remove heavy energies (psychic protection). <strong>Contraindicated with blood thinners (warfarin, anticoagulants) - increases bleeding risk; wait 3 or more hours after meds before using.</strong>$$
WHERE common_name = 'Garlic';
